<?php require __DIR__.'/../../includes/admin_auth.php';$pdo=db();$bid=(int)$_GET['book_id'];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare("INSERT INTO book_copies(book_id,accession_number,status,location,`condition`) VALUES(?,?,'AVAILABLE',?,?)")->execute([$bid,trim($_POST['accession_number']),trim($_POST['location']),trim($_POST['condition'])]);flash('success','Physical copy added.');header('Location: copies.php?book_id='.$bid);exit;}$s=$pdo->prepare('SELECT title FROM books WHERE id=?');$s->execute([$bid]);$title=$s->fetchColumn();$s=$pdo->prepare('SELECT * FROM book_copies WHERE book_id=?');$s->execute([$bid]);$rows=$s->fetchAll();$pageTitle='Book copies';require __DIR__.'/../../includes/header.php';?><h1>Copies: <?=e($title?:'Unknown book')?></h1><div class="panel"><form method="post" class="toolbar"><input type="hidden" name="csrf" value="<?=csrf()?>"><input required name="accession_number" placeholder="Accession number"><input name="location" placeholder="Shelf location"><input name="condition" value="Good" placeholder="Condition"><button>Add copy</button></form><table><tr><th>Accession number</th><th>Status</th><th>Location</th><th>Condition</th></tr><?php foreach($rows as $c):?><tr><td><?=e($c['accession_number'])?></td><td><?=e($c['status'])?></td><td><?=e($c['location'])?></td><td><?=e($c['condition'])?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../../includes/footer.php'; ?>
